select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Activepieces' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme d''automatisation open source pour créer des processus, des agents IA, des tables et des serveurs MCP, dans le cloud ou hébergée chez vous.',
  'Open-source automation platform to build workflows, AI agents, tables and MCP servers, in the cloud or self-hosted.');
