select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Activepieces', 'Retool Agents', 'Dify', 'Remy (formerly MindStudio)', 'Pipedream', 'Klaviyo Customer Agent', 'Continue', 'Lyzr Agent Studio', 'Vellum') order by e.name;
